-- PostgreSQL 18 guc_tables.c defines the planner settings ("Query Tuning")
-- and explain.c prints Disabled: true on a node whose method is disabled.
CREATE TABLE t375 (a int PRIMARY KEY, b int);
CREATE TABLE u375 (a int, c int);
INSERT INTO t375 SELECT g, g % 10 FROM generate_series(1, 1000) g;
INSERT INTO u375 SELECT g, g FROM generate_series(1, 100) g;
ANALYZE t375;
ANALYZE u375;
SHOW enable_seqscan;
SET enable_bitmapscan = off;
SET enable_indexscan TO false;
EXPLAIN (COSTS OFF) SELECT * FROM t375 WHERE a = 5;
SELECT * FROM t375 WHERE a = 5;
SET enable_seqscan = 0;
EXPLAIN (COSTS OFF) SELECT * FROM u375 WHERE c = 3;
EXPLAIN (COSTS OFF, FORMAT JSON) SELECT * FROM u375;
EXPLAIN (COSTS OFF, SETTINGS) SELECT * FROM u375;
RESET enable_indexscan;
EXPLAIN (COSTS OFF, SETTINGS) SELECT * FROM t375 WHERE a = 5;
RESET ALL;
EXPLAIN (COSTS OFF) SELECT * FROM t375 JOIN u375 ON t375.b = u375.a;
BEGIN;
SET LOCAL enable_hashjoin = off;
SHOW enable_hashjoin;
SET LOCAL work_mem = '1MB';
EXPLAIN (COSTS OFF, SETTINGS) SELECT * FROM t375 WHERE a = 5;
ROLLBACK;
SHOW enable_hashjoin;
SET enable_bitmapscan = 'maybe';
SET enable_seqscan = 2;
SET cpu_tuple_cost = -1;
SET cpu_tuple_cost = 'abc';
SET geqo_effort = 11;
SET geqo_selection_bias = 1;
SET jit_above_cost = -2;
SET recursive_worktable_factor = 0;
SET effective_cache_size = 0;
SET plan_cache_mode = 'x';
SET constraint_exclusion = 'ON';
SHOW constraint_exclusion;
SET cpu_tuple_cost = 0.000001234567;
SHOW cpu_tuple_cost;
SET random_page_cost = 1234567;
SHOW random_page_cost;
SET effective_cache_size = 1000;
SHOW effective_cache_size;
SET min_parallel_table_scan_size = '16MB';
SHOW min_parallel_table_scan_size;
SET geqo = yes;
SELECT current_setting('enable_mergejoin'), set_config('enable_memoize', 'off', false);
SELECT name, setting, unit, category, short_desc, context, vartype, source, min_val, max_val, enumvals, boot_val, reset_val
FROM pg_settings WHERE category LIKE 'Query Tuning%' ORDER BY name;
EXPLAIN (COSTS OFF, SETTINGS) SELECT 1;
RESET ALL;
CREATE FUNCTION f375() RETURNS text LANGUAGE sql SET enable_sort = off AS $$ SELECT current_setting('enable_sort') $$;
SELECT f375(), current_setting('enable_sort');
